"use client";

import { spring } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  type AnimatedBarChartElementId,
  animatedBarChartTimeline,
  DEFAULT_DATA,
} from "./timeline";

export interface AnimatedBarChartProps {
  data?: number[];
  labels?: string[];
  width?: number;
  height?: number;
  barColor?: string;
  gap?: number;
  staggerFrames?: number;
  speed?: number;
  className?: string;
  /**
   * Moves, trims or stretches single bars, by the ids in `./timeline`.
   * Frames on the scene timeline, after `speed`.
   */
  timing?: Timing<AnimatedBarChartElementId>;
}

export function AnimatedBarChart(props: AnimatedBarChartProps) {
  const {
    data = DEFAULT_DATA,
    labels,
    width = 1000,
    height = 500,
    barColor = "#0ea5e9",
    gap = 16,
    speed = 1,
    className,
    timing,
  } = props;
  const frame = useSceneFrame() * speed;
  const { fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    animatedBarChartTimeline,
    props,
    durationInFrames * speed,
    timing,
  );

  const padding = 60;
  const labelSpace = labels ? 40 : 0;
  const innerWidth = width - padding * 2;
  const innerHeight = height - padding * 2 - labelSpace;
  const max = Math.max(...data);
  const barWidth = (innerWidth - gap * (data.length - 1)) / data.length;
  const baseY = padding + innerHeight;

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontFamily:
          "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
      }}
    >
      <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`}>
        {/* Baseline */}
        <line
          x1={padding}
          x2={padding + innerWidth}
          y1={baseY}
          y2={baseY}
          stroke="#27272a"
          strokeWidth={2}
        />

        {data.map((value, index) => {
          const targetHeight = (value / max) * innerHeight;
          const x = padding + index * (barWidth + gap);
          const y = baseY - targetHeight;

          const scaleY = spring({
            frame: frame - tl.get(`bar:${index}`).start,
            fps,
            config: { damping: 12, stiffness: 100, mass: 0.8 },
            from: 0,
            to: 1,
          });

          return (
            <g key={index}>
              <rect
                x={x}
                y={y}
                width={barWidth}
                height={targetHeight}
                rx={6}
                fill={barColor}
                style={{
                  scale: `1 ${scaleY}`,
                  transformOrigin: `${x + barWidth / 2}px ${baseY}px`,
                  transformBox: "fill-box",
                  filter: `drop-shadow(0 4px 16px ${barColor}55)`,
                }}
              />
              {labels?.[index] && (
                <text
                  x={x + barWidth / 2}
                  y={baseY + 28}
                  fill="#a1a1aa"
                  fontSize={16}
                  textAnchor="middle"
                  style={{
                    opacity: scaleY,
                    fontFamily:
                      "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
                  }}
                >
                  {labels[index]}
                </text>
              )}
            </g>
          );
        })}
      </svg>
    </div>
  );
}

import { defineTimeline } from "@/lib/remocn/timeline";

// When each bar springs up from the baseline. Frames on the 30 fps scene
// timeline, after `speed`. The ids are public: a saved `timing` prop refers
// to them.

export type AnimatedBarChartElementId = `bar:${number}`;

export interface AnimatedBarChartTimingProps {
  data?: number[];
  labels?: string[];
  staggerFrames?: number;
}

export const DEFAULT_DATA = [35, 60, 45, 80, 55, 70, 90, 65];
const STAGGER_FRAMES = 6;
/** Frames the bar's spring takes to settle. */
const RISE = 19;

// `bar:<i>` springs bar `i` up, `staggerFrames` after the one before; a chain.
export const animatedBarChartTimeline = defineTimeline<
  AnimatedBarChartElementId,
  AnimatedBarChartTimingProps
>(({ data = DEFAULT_DATA, labels, staggerFrames = STAGGER_FRAMES }) =>
  data.map((value, i) => ({
    id: `bar:${i}`,
    lane: "Bars",
    label: labels?.[i] ?? String(value),
    start: i * staggerFrames,
    length: RISE,
    follows: i > 0 ? `bar:${i - 1}` : undefined,
  })),
);
